        assertEquals(2, r1.path("activeSealCount").asInt());
        assertEquals(3, r1.path("rangeLabelCount").asInt());
        assertEquals(1, r1.path("remainingLabels").asInt());
        assertFalse(r1.path("reconciled").asBoolean());

