        // 已放行：封箱/作废均 409
        sealBoxesRaw(batchKey, List.of(seal(100, 1)), "CK-SEAL-AFTER", 409);
        voidSeals(batchKey, List.of(voidItem(100, "放行后作废")), "CK-VOID-AFTER", 409);

        // 快照与诊断不随后续操作改变（读取不改状态），诊断无差异
        JsonNode snapAgain = snapshot(batchKey);
