 */
private void assertBatchAllowsLabelOps(BatchStatus status) {
    if (status == BatchStatus.RECALLED || status == BatchStatus.RELEASED
            || status == BatchStatus.SPLIT || status == BatchStatus.REJECTED) {
        throw ApiException.conflict("批次状态 " + status + " 不允许标签登记、封箱或作废");
